[=[return {c={"Auto-accept summon (testing)","Auto-gossip (testing)","Darkmoon Faire (Sayge)","Auto quest turn-ins (testing)"},e={{"t","Settings for:",1,0,0,"Alliance Edit the automation used on your Alliance characters. Horde Edit the automation used on your Horde characters."},{"r","Settings for:",1,0,0},{"r","Alliance",1,0,0},{"r","Accept Summon",1,0,0},{"r","Gossip",1,0,0},{"r","Quest",1,0,0},{"c","Auto-accept summon (testing)",1,1,0},{"r","FFF Fire Festival Fury",1,1,0},{"r","DMT SP Slip'kik's Savvy",1,1,0},{"r","DMT AP Fengus' Ferocity",1,1,0},{"r","ZG Spirit of Zandalar",1,1,0},{"r","DMT STAM Mol'dar's Moxie",1,1,0},{"r","Rend Warchief's Blessing",1,1,0},{"r","SF Songflower Serenade",1,1,0},{"r","BS Battle Shout",1,1,0},{"r","Ony Rallying Cry of the Dragonslayer",1,1,0},{"r","Taxi PVP drop (accept when PVP flag drops on a taxi)",1,1,0},{"r","Enable auto-accept summon",1,1,0},{"r","Always accept summon (ignore buff triggers)",1,1,0},{"r","DMF Sayge's Dark Fortune of Damage",1,1,0},{"d","DMF Sayge's Dark Fortune of Damage",1,1,0,"Automatically accept a pending summon when a selected tracked buff is freshly gained. A buff is fresh if it was not previously active (not from un-booning) or if its duration jumped significantly. The accept window runs from the moment the fresh buff is detected."},{"r","Auto-accept window (seconds, 5–3600):",1,1,0},{"r","Buff triggers - which fresh buffs arm the auto-accept:",1,1,0},{"t","Settings for:",2,0,0,"Alliance Edit the automation used on your Alliance characters. Horde Edit the automation used on your Horde characters."},{"r","Settings for:",2,0,0},{"r","Alliance",2,0,0},{"r","Accept Summon",2,0,0},{"r","Gossip",2,0,0},{"r","Quest",2,0,0},{"c","Auto-gossip (testing)",2,2,0},{"r","Auto-use Orb of Command",2,2,0},{"r","Auto-accept DMT buffs",2,2,0},{"d","Auto-accept DMT buffs",2,2,0,"Dire Maul Tribute: auto-accept buffs from the DMT guards (Mol'dar, Fengus, Slip'kik, Mizzle, Komcrush) on gossip open."},{"r","BWL Portal: automatically use the Orb of Command on gossip open.",2,2,0},{"c","Darkmoon Faire (Sayge)",2,3,0},{"r","Auto-select DMF buff from Sayge",2,3,0},{"r","Skip fortune cookie (auto-close gossip after buff)",2,3,0},{"d","Skip fortune cookie (auto-close gossip after buff)",2,3,0,"Automatically select your DMF fortune from Sayge on gossip open. Use with caution - this instantly picks your buff on NPC click."},{"r","Buff type per class:",2,3,0},{"r","Warrior",2,3,0},{"r","Damage (+10% Dmg)",2,3,0},{"r","Rogue",2,3,0},{"r","Hunter",2,3,0},{"r","Mage",2,3,0},{"r","Warlock",2,3,0},{"r","Priest",2,3,0},{"r","Druid",2,3,0},{"r","Paladin",2,3,0},{"t","Settings for:",3,0,0,"Alliance Edit the automation used on your Alliance characters. Horde Edit the automation used on your Horde characters."},{"r","Settings for:",3,0,0},{"r","Alliance",3,0,0},{"r","Accept Summon",3,0,0},{"r","Gossip",3,0,0},{"r","Quest",3,0,0},{"c","Auto quest turn-ins (testing)",3,4,0},{"r","Auto-turn-in Rage of Ages (R.O.I.D.S.)",3,4,0},{"r","Pick Spirit of Zanza",3,4,0},{"r","Pick Sheen of Zanza",3,4,0},{"r","Auto-repair gear at Rin'wosho after turn-in",3,4,0},{"r","Pick Swiftness of Zanza",3,4,0},{"r","Auto-turn-in Zandalar Honor Tokens",3,4,0},{"r","Auto-turn-in E'ko quests",3,4,0},{"r","Auto-turn-in Yojamba coin quests",3,4,0},{"d","Auto-turn-in Yojamba coin quests",3,4,0,"Hold Shift while opening an NPC's gossip to skip any auto turn-in once."},{"r","Winterspring E'ko - turn in all E'ko types at Witch Doctor Mau'ari.",3,4,0},{"r","Yojamba Isle Coins - turn in complete ZG coin sets at Vinchaxa.",3,4,0},{"d","Yojamba Isle Coins - turn in complete ZG coin sets at Vinchaxa.",3,4,0,"Yojamba Isle Zanza - turn in Zandalar Honor Tokens at Rin'wosho, picking the first enabled zanza you don't already own (bag + bank snapshot aware)."},{"d","Yojamba Isle Coins - turn in complete ZG coin sets at Vinchaxa.",3,4,0,"Blasted Lands R.O.I.D.S. - auto-accept and auto-complete Rage of Ages at Bloodmage Drazial (needs 3x Jowl, 2x Lung, 1x Pincer)."}},f={},p={["summon,gossip,quest=gossip"]={{key="gossip",label="Gossip",many=true,sig="summon,gossip,quest"}},["summon,gossip,quest=quest"]={{key="quest",label="Quest",many=true,sig="summon,gossip,quest"}},["summon,gossip,quest=summon"]={{key="summon",label="Accept Summon",many=true,sig="summon,gossip,quest"}}},t={"summon,gossip,quest=summon","summon,gossip,quest=gossip","summon,gossip,quest=quest"}}]=],
